#ifndef MY_NODE
#define MY_NODE 0x02
#endif

/* This hub's 2 LOCAL link(s) (ADR-0006):
      link 0 (up): the host UART (the root owns the host link)
      link 1: uart → node(s) 0x05
   */
#define BLASTER_N_LINKS 2

/* Optional per-loop telemetry hook (§08). The glue calls blaster_post_control() at
   the end of every control_tick. The device file can provide its own by doing
   `#define BLASTER_POST_CONTROL_OVERRIDE` BEFORE including this header (then
   implementing blaster_post_control() itself); otherwise this no-op default is used. */
#ifndef BLASTER_POST_CONTROL_OVERRIDE
extern "C" void blaster_post_control(void) {}
#endif


/* Per-sensor seq — advanced only on a real new value (§04). */
static uint16_t g_seq_range_front = 0;
static uint16_t g_seq_pose = 0;

/* A command for status_led: NOT floored (safe_action == nil), so decode the
   value and drive the device directly — a stale command is harmless (§09). */
static void on_command_status_led(const Frame *f) {
  if (f->port != PORT_BLASTER_STATUS_LED) return;
  if (f->payload_len < 3) return;
  Led v;
  v.r = f->payload[0];
  v.g = f->payload[1];
  v.b = f->payload[2];
  blaster_status_led_drive(&v);
}

/* IN ports are event-driven via on_command; the scheduled cmd tick is a no-op. */
static void status_led_cmd_tick(uint32_t now_us) { (void)now_us; }

/* Sense range_front (§08): one bounded read, pack big-endian, send up. A read
   that fails returns → no write → the seq stalls → the reader goes stale. */
static void range_front_sample_tick(uint32_t now_us) {
  Range raw;
  if (!blaster_range_front_read(&raw)) return;

  Frame f;
  f.node = MY_NODE;
  f.port = PORT_BLASTER_RANGE_FRONT;
  f.seq = ++g_seq_range_front;        /* advance only on a real new value */
  f.stamped = PORT_BLASTER_RANGE_FRONT_STAMPED;
  f.t_dev = 0;
  (void)now_us;

  be_put_f32(&f.payload[0], raw.distance_m);
  f.payload_len = 4;

  link_send_up(&f);
}

/* Sense pose (§08): one bounded read, pack big-endian, send up. A read
   that fails returns → no write → the seq stalls → the reader goes stale. */
static void pose_sample_tick(uint32_t now_us) {
  Imu raw;
  if (!blaster_pose_read(&raw)) return;

  Frame f;
  f.node = MY_NODE;
  f.port = PORT_BLASTER_POSE;
  f.seq = ++g_seq_pose;        /* advance only on a real new value */
  f.stamped = PORT_BLASTER_POSE_STAMPED;
  f.t_dev = now_us;                 /* this hub's own µs, same-device use only */

  be_put_f32(&f.payload[0], raw.qw);
  be_put_f32(&f.payload[4], raw.qx);
  be_put_f32(&f.payload[8], raw.qy);
  be_put_f32(&f.payload[12], raw.qz);
  be_put_f32(&f.payload[16], raw.wx);
  be_put_f32(&f.payload[20], raw.wy);
  be_put_f32(&f.payload[24], raw.wz);
  be_put_f32(&f.payload[28], raw.ax);
  be_put_f32(&f.payload[32], raw.ay);
  be_put_f32(&f.payload[36], raw.az);
  f.payload_len = 40;

  link_send_up(&f);
}
static Router g_router;

static void deliver_local(const Frame *f, void *) {
  if (f->port == PORT_BLASTER_STATUS_LED) on_command_status_led(f);
}
static void send_on_link(uint8_t link, const Frame *f, void *) {
  link_send_on_link(link, f); /* link 0 = host UART (up); downlinks 1..N = backplanes (ADR-0006) */
}


/* Meaning-blind inbound (§04): decode the body (CRC-clean at the seam), learn
   t_dev-ness per port just-in-time, route by DIRECTION + NODE (ADR-0006,
   ADR-0011): a downlink arrival ascends to link 0; a parent arrival is
   dispatched by NODE → a LOCAL LINK INDEX. seq/t_dev never touched. */
extern "C" void hub_on_body(uint8_t arrival_link, const uint8_t *body, size_t len) {
  if (len < FRAME_HEADER_BASE_SIZE) return;
  Frame f;
  bool stamped = wire_port_stamped(body[0], body[1]); /* per-port t_dev (§04) */
  if (!frame_decode_body(body, len, stamped, &f)) return;
  RouterSinks sinks = {deliver_local, send_on_link, nullptr};
  router_route(&g_router, &f, arrival_link, &sinks);
}
extern "C" void hub_setup(void) {
  g_router.my_node = MY_NODE;
  for (int i = 0; i < 256; i++) g_router.route_table[i] = 0; /* default: link 0, the up-link toward the parent/host */
  g_router.route_table[0x02] = LINK_LOCAL_IDX; /* MY_NODE — delivered to a local port */
  g_router.route_table[0x05] = 1; /* reached via downlink 1 (ADR-0006) */

  blaster_device_setup(); /* the hand-written hardware bring-up */
}
/* The schedule (§08): one {period_us, tick} row per port from its rate. A
   sense-only hub has no control_tick. */
static Task blaster_tasks[] = {
  { 50000, 0, range_front_sample_tick }  /* range_front @ 20 Hz */,
  { 50000, 0, status_led_cmd_tick }  /* status_led @ 20 Hz */,
  { 10000, 0, pose_sample_tick }  /* pose @ 100 Hz */
};
#define BLASTER_N_TASKS (sizeof(blaster_tasks) / sizeof(blaster_tasks[0]))

extern "C" Task *hub_tasks(size_t *n_tasks) {
  *n_tasks = BLASTER_N_TASKS;
  return blaster_tasks;
}
